package coupons.serialization;

import java.io.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Golden bytes were generated by commit c4c29925 before any Java package moves. */
class LegacyObjectStreamsTest {
    private byte[] fixture() throws IOException {
        try(var stream=getClass().getResourceAsStream("/serialization/legacy-objects.bin")) {
            assertNotNull(stream); return stream.readAllBytes();
        }
    }
    private Object read(byte[] bytes) throws Exception {
        try(var stream=LegacyObjectStreams.input(new ByteArrayInputStream(bytes))) {return stream.readObject();}
    }
    private Map<String,String> descriptors(byte[] bytes) throws Exception {
        var descriptors=new TreeMap<String,String>();
        try(var stream=new ObjectInputStream(new ByteArrayInputStream(bytes)) {
            @Override protected ObjectStreamClass readClassDescriptor() throws IOException,ClassNotFoundException {
                var d=super.readClassDescriptor();var fields=new StringJoiner(",");
                for(var f:d.getFields())fields.add(f.getName()+":"+(f.isPrimitive()?f.getTypeCode():f.getTypeString()));
                descriptors.put(d.getName(),d.getSerialVersionUID()+":"+fields);return d;
            }
            @Override protected Class<?> resolveClass(ObjectStreamClass d) throws IOException,ClassNotFoundException {
                // Inspection resolves with the production reader so legacy packages may be absent.
                return resolveCurrent(d.getName());
            }
        }) {stream.readObject();}
        return descriptors;
    }
    private Class<?> resolveCurrent(String name) throws ClassNotFoundException {
        // Keep this inspector independent of the production map: compare captured wire names separately.
        try {return Class.forName(name);}catch(ClassNotFoundException absent){
            for(String feature:List.of("inventory","shopping","rewards","promotions","receipts","cli","distributed")) {
                int start=name.lastIndexOf('[')+1;if(name.endsWith(";")&&name.charAt(start)=='L')start++;
                if(!name.startsWith("coupons.",start))continue;
                String candidate=name.substring(0,start)+"coupons."+feature+"."+name.substring(start+8);
                try{return Class.forName(candidate);}catch(ClassNotFoundException next){}
            }
            throw absent;
        }
    }
    @Test void readsExistingSnapshotsPlansDraftsAndHistoryWithoutMigration() throws Exception {
        var values=(Map<?,?>)read(fixture());
        assertEquals(Set.of("state","receipt","draft","plan","purchase","coupon","dealTerms","worksheet","details","couponArray","enumContracts"),values.keySet());
        var plan=values.get("plan");var scenario=plan.getClass().getMethod("scenario").invoke(plan);
        var lines=(List<?>)scenario.getClass().getMethod("items").invoke(scenario);var line=lines.getFirst();
        assertEquals(new BigDecimal("0.12345678901234567890"),line.getClass().getMethod("sale").invoke(line));
    }
    @Test void writesTheOriginalClassNamesUidsAndFieldSignaturesForRollback() throws Exception {
        byte[] original=fixture();var bytes=new ByteArrayOutputStream();
        try(var writer=LegacyObjectStreams.output(bytes)){writer.writeObject(read(original));}
        assertEquals(descriptors(original),descriptors(bytes.toByteArray()));
        var restored=(Map<?,?>)read(bytes.toByteArray());assertEquals(((Map<?,?>)read(original)).keySet(),restored.keySet());
    }
}
